package com.pp.shaderlod.optimization.photonearlyalpha;import java.util.*;import com.google.gson.*;public final class PhotonEarlyAlphaProfile{private PhotonEarlyAlphaProfile(){}private static final Map<String,String> EXPECTED=load();private static Map<String,String> load(){try(var in=PhotonEarlyAlphaProfile.class.getResourceAsStream("/assets/shaderlod/photonearlyalpha/optional394.json")){if(in==null)return Map.of();byte[] b=in.readAllBytes();if(!java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(b)).equals("0ba649f93425bd223b46ee0de06dbc138bc074b30d901e58e679051509dc554b"))return Map.of();var m=new TreeMap<String,String>();for(var e:JsonParser.parseString(new String(b,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet())m.put(e.getKey(),e.getValue().getAsString());return m.size()==395?Map.copyOf(m):Map.of();}catch(Exception|LinkageError e){return Map.of();}}private static boolean normalize(Map<String,String> m){if(m==null||!("0".equals(m.get("SHADERLOD_PHOTON_DEPTH_PRIMING"))||"1".equals(m.get("SHADERLOD_PHOTON_DEPTH_PRIMING"))))return false;var n=new TreeMap<>(m);n.put("SHADERLOD_PHOTON_DEPTH_PRIMING","0");return EXPECTED.equals(n);}public static boolean accepts(Map<String,String> m){return EXPECTED.size()==395&&normalize(m);}}
